/**
 * 全球热门 MV 核验库（2026-10-27 v1，浏览器人工核验 1057 首）。
 *
 * 数据来源：ZCode 浏览器自动化在 B 站登录态下逐首搜索（歌名+歌手），对前 8 名候选经
 * view API 核验（标题/UP主/mid/时长/播放数），按规则自动挑选：
 *   1) UP 主名 = 歌手名（author-artist-match）
 *   2) 标题含官方标记且非转录号（official-marker）
 *   3) 标题含 MV/Official 标记 + 非转录号最高播放（mv-marker-top-play）
 *   4) 非转录号最高播放（top-play-non-translator）
 * 全程排除伴奏/翻唱/Remix/转录号（JLRS 三马甲）/加长循环/卡拉OK/教学/谱面。
 *
 * 命中管道：songKey 精确命中不可用（本库以「歌手+歌名」为锚），走元数据回退索引
 * （规范化标题+主歌手+时长 ±10s 容差）——与 bilibiliOpEdExtensions 同口径，
 * 由 services/bilibiliApi.resolveOpEdExtensionEntry 的 findOpEdExtensionByMeta 消费。
 *
 * 覆盖：72 位主流艺人（欧美/日/华/韩/其他），每艺人 8-15 首代表作。
 */
export interface GlobalCatalogEntry {
  /** 规范化「歌名|主歌手」元数据键（与 bilibiliOpEdExtensions 元数据索引同构） */
  songTitle: string
  artists: readonly string[]
  bvid: string
  videoTitle: string
  /** UP 主名称（回溯用） */
  uploader: string
  uploaderMid: number
  /** 歌曲口径时长（秒）——该视频的时长，元数据回退时与实际歌曲时长做 ±10s 容差 */
  duration: number
  playCount: number
  /** 挑选依据：author-artist-match / official-marker / mv-marker-top-play / top-play-non-translator */
  reason: string
  verifiedAt: string
}

export const GLOBAL_CATALOG_VERSION = '2026-10-27-1'

/** 元数据索引：规范化「歌名|主歌手」→ 候选条目（含时长），与 bilibiliOpEdExtensions 元数据索引同构。 */
const normalizeForCatalogIndex = (value: string): string =>
  String(value || '')
    .normalize('NFC')
    .toLowerCase()
    .replace(/[（()）\[\]【】《》<>{}"''“”·…!！?？,，.。｡;；:：\-—_／/\|&*^%$#@~`+=～~]/g, '')
    .replace(/\s+/g, '')

const stripVersionSuffix = (value: string): string =>
  String(value || '')
    .replace(/\s*[（(][^（）()]*[）)]\s*$/, '')
    .replace(/\s*[-–—]\s*(?:TV|Anime|Full|Short|Movie|剧场版|Sped|Slowed)\s*(?:Size|Ver(?:sion)?|Edit|Up)?.*$/i, '')
    .replace(/\s*(?:完整版|加长版|加長版|TV版|tv版|アニメサイズ|フルサイズ|电视版|纯音乐|伴奏|Live版|现场版)\s*$/i, '')
    .trim()



/** 时长接近判定（±10s，与延长库同口径）。 */
const isDurationClose = (a: number, b: number): boolean => {
  if (!a || !b) return true
  return Math.abs(a - b) <= 10
}

/**
 * 全球目录元数据查找：规范化歌名+主歌手（剥版本后缀），时长 ±10s 容差。
 * 主歌手键未中时遍历歌名桶（feat. 写法差异兜底），要求歌手互相包含。
 * 返回 null = 库内无此歌（正常回退到普通搜索匹配）。
 */
export function findGlobalCatalogByMeta(songTitle: string, artists: readonly string[], duration?: number): GlobalCatalogEntry | null {
  const title = normalizeForCatalogIndex(stripVersionSuffix(songTitle))
  if (!title || title.length < 2) return null
  const firstArtist = artists?.[0] ? normalizeForCatalogIndex(artists[0]) : ''
  const hit = CATALOG_META_INDEX.get(`${title}|${firstArtist}`)
  if (hit && isDurationClose(hit.duration, duration || 0)) return hit
  for (const [key, entry] of CATALOG_META_INDEX) {
    if (!key.startsWith(`${title}|`)) continue
    const keyArtist = key.slice(title.length + 1)
    if (firstArtist && keyArtist && !keyArtist.includes(firstArtist) && !firstArtist.includes(keyArtist)) continue
    if (isDurationClose(entry.duration, duration || 0)) return entry
  }
  return null
}

/** 按 bvid 查询（候选评分时的已知正片判断）。 */
export function getGlobalCatalogEntryByBvid(bvid: string): GlobalCatalogEntry | null {
  return GLOBAL_CATALOG_ENTRIES.find((e) => e.bvid === bvid) || null
}

