const CATALOG_META_INDEX: ReadonlyMap<string, GlobalCatalogEntry> = (() => {
  const map = new Map<string, GlobalCatalogEntry>()
  for (const entry of GLOBAL_CATALOG_ENTRIES) {
    const title = normalizeForCatalogIndex(stripVersionSuffix(entry.songTitle))
    if (!title) continue
    const firstArtist = entry.artists[0] ? normalizeForCatalogIndex(entry.artists[0]) : ''
    const key = `${title}|${firstArtist}`
    // 同键冲突取播放数高者（生成时已去重，此处兜底）
    const prev = map.get(key)
    if (!prev || entry.playCount > prev.playCount) map.set(key, entry)
  }
  return map
})()

